        <CreateProjectScreen />
      ) : weeklyReview ? (
        <WeeklyReview route={route} />
      ) : history ? (
        <History route={route} />
      ) : availability ? (
        <Availability />
      ) : sessionRoute ? (
        <WorkSessionReader
          key={route}
          projectId={sessionRoute[1]}
          taskId={sessionRoute[2]}
          id={sessionRoute[3]}
        />
      ) : taskRoute ? (
        <TaskReader
          key={route}
          projectId={taskRoute[1]}
          id={taskRoute[2]}
